import { Component, OnInit, OnDestroy, signal, ElementRef, ViewChild, HostListener } from '@angular/core';
import { RouterOutlet } from '@angular/router';
import { LangService } from '../../services/lang.service';
import { AuthService } from '../../services/auth.service';
import { Router } from '@angular/router';
import { TranslationService } from '../../services/translation.service';
import { ProfileService, UserProfile } from '../../services/profile.service';
import { ImageService } from '../../services/image.service';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-layout',
  templateUrl: './layout.component.html',
  styleUrls: ['./layout.component.css'],
  standalone: false
})
export class LayoutComponent implements OnInit, OnDestroy {
  isRTL = signal(false);
  user:any
  sidebarCollapsed = signal(false);
  currentLang = signal<'ar' | 'en'>('en');
  showLogoutConfirm = signal(false);
  showNotificationModal = signal(false);
  isMobile = signal(false);
  mobileSidebarOpen = signal(false);
  showProfileMenu = signal(false);
  profileMenuId = 'profile-menu-panel';
  private readonly defaultAvatar = 'assets/images/user.png';
  private profileSubscription?: Subscription;
  private userProfile: UserProfile | null = null;

  @ViewChild('profileMenuContainer') profileMenuContainer?: ElementRef<HTMLElement>;

  private resizeListener = () => this.checkScreenSize();

  constructor(
    private langService: LangService,
    private authService: AuthService,
    private router: Router,
    private translationService: TranslationService,
    private profileService: ProfileService,
    private imageService: ImageService
  ) {}

  ngOnInit(): void {
    // Subscribe to language changes
    this.langService.currentLang$.subscribe((lang: 'ar' | 'en') => {
      this.currentLang.set(lang);
      this.isRTL.set(lang === 'ar');
      const stored=localStorage.getItem('user');
      this.user=stored?JSON.parse(stored):null;
    });

    this.loadUserProfile();
    
    // Check initial screen size
    this.checkScreenSize();
    
    // Add resize listener
    window.addEventListener('resize', this.resizeListener);
    
  }

  onSidebarCollapsed(collapsed: boolean): void {
    this.sidebarCollapsed.set(collapsed);
  }

  setLanguage(lang: 'ar' | 'en'): void {
    this.langService.setLanguage(lang);
    console.log('Language changed to:', lang);
  }

  toggleLanguage(): void {
    this.langService.toggleLanguage();
  }

  onLogoutConfirmRequested(): void {
    this.showLogoutConfirm.set(true);
  }

  closeLogoutConfirm(): void {
    this.showLogoutConfirm.set(false);
  }

  // Notification modal methods
  openNotificationModal(): void {
    this.showNotificationModal.set(true);
  }

  closeNotificationModal(): void {
    this.showNotificationModal.set(false);
  }

  onSendNotification(notification: any): void {
    // Handle notification sending logic here
    this.closeNotificationModal();
  }

  logout(): void {
    this.showLogoutConfirm.set(false);
    this.authService.logout().subscribe({
      next: () => {
        this.router.navigate(['/auth/login']);
      },
      error: (error) => {
        console.error('Logout error:', error);
        this.router.navigate(['/auth/login']);
      }
    });
  }

  translate(key: string): string {
    return this.translationService.translate(key);
  }

  private checkScreenSize(): void {
    const isMobile = window.innerWidth <= 768;
    this.isMobile.set(isMobile);
    
    // Close mobile sidebar when switching to desktop
    if (!isMobile && this.mobileSidebarOpen()) {
      this.mobileSidebarOpen.set(false);
    }
  }

  toggleMobileSidebar(): void {
    this.mobileSidebarOpen.update(open => !open);
  }

  closeMobileSidebar(): void {
    this.mobileSidebarOpen.set(false);
  }

  toggleProfileMenu(event: MouseEvent): void {
    event.stopPropagation();
    this.showProfileMenu.update(open => !open);
  }

  private closeProfileMenu(): void {
    if (this.showProfileMenu()) {
      this.showProfileMenu.set(false);
    }
  }

  onProfileMenuSelect(action: 'profile' | 'logout'): void {
    this.closeProfileMenu();
    if (action === 'profile') {
      this.navigateToProfile();
    } else {
      this.onLogoutConfirmRequested();
    }
  }

  navigateToProfile(): void {
    this.router.navigate(['/profile']);
  }

  getUserFullName(): string {
    if (this.userProfile) {
      const first = this.userProfile.firstName || '';
      const last = this.userProfile.lastName || '';
      const fullName = `${first} ${last}`.trim();
      if (fullName) {
        return fullName;
      }
      if (this.userProfile.email) {
        return this.userProfile.email;
      }
    }
    if (this.user) {
      const first = this.user.firstName || '';
      const last = this.user.lastName || '';
      const fullName = `${first} ${last}`.trim();
      if (fullName) {
        return fullName;
      }
      if (this.user.email) {
        return this.user.email;
      }
    }
    return this.translate('login.profile');
  }

  getUserInitials(): string {
    if (this.userProfile) {
      const first = (this.userProfile.firstName || '').charAt(0);
      const last = (this.userProfile.lastName || '').charAt(0);
      const initials = `${first}${last}`.trim();
      if (initials) {
        return initials.toUpperCase();
      }
      if (this.userProfile.email) {
        return this.userProfile.email.charAt(0).toUpperCase();
      }
    }
    if (this.user) {
      const first = (this.user.firstName || '').charAt(0);
      const last = (this.user.lastName || '').charAt(0);
      const initials = `${first}${last}`.trim();
      if (initials) {
        return initials.toUpperCase();
      }
      if (this.user.email) {
        return this.user.email.charAt(0).toUpperCase();
      }
    }
    return 'U';
  }

  getUserImageUrl(): string {
    if (this.userProfile) {
      return this.imageService.getImageUrl(this.userProfile.imageUrl, this.getUserFullName());
    }
    if (this.user?.imageUrl) {
      return this.user.imageUrl;
    }
    return this.defaultAvatar;
  }

  onAvatarError(event: Event): void {
    const target = event.target as HTMLImageElement;
    if (target && target.src !== this.defaultAvatar) {
      target.src = this.defaultAvatar;
    }
  }

  ngOnDestroy(): void {
    // Clean up resize listener
    window.removeEventListener('resize', this.resizeListener);
    if (this.profileSubscription) {
      this.profileSubscription.unsubscribe();
    }
  }

  @HostListener('document:click', ['$event'])
  onDocumentClick(event: MouseEvent): void {
    if (!this.showProfileMenu()) {
      return;
    }

    const target = event.target as HTMLElement;
    const container = this.profileMenuContainer?.nativeElement;

    if (container && !container.contains(target)) {
      this.closeProfileMenu();
    }
  }

  @HostListener('document:keydown.escape')
  onEscapePress(): void {
    this.closeProfileMenu();
  }

  private loadUserProfile(): void {
    this.profileSubscription = this.profileService.getProfile().subscribe({
      next: (response) => {
        if (response.success && response.data) {
          this.userProfile = response.data;
        }
      },
      error: (error) => {
        console.error('Error loading user profile for header:', error);
      }
    });
  }
}
